/**
 * Ramus v2 local visual catalog. All specimens render the sibling React APIs.
 * Independent reconstruction, not the original service production implementation.
 * React only; no requests, persistence, account actions, remote assets or logos.
 * Load order: ramus.css -> ramus-primitives.css -> ramus-patterns.css -> ramus-advanced.css -> catalog.css.
 */
import * as React from "react";
import { RamusProvider, Button, RadioChips, TextField, RoleCombobox, AppCard, StepProgress, CatalogDialog, Demo } from "./RamusComponents";
import type { RamusTheme } from "./RamusComponents";
import { ButtonV2, InputV2, LabelV2, TextareaV2, Checkbox, Switch, RadioControl, Avatar, Badge, Select, DropdownMenu, Tooltip, Popover, HoverCard, Tabs, ScrollArea, Separator, Skeleton, Spinner } from "./RamusPrimitives";
import type { ButtonV2Variant, ButtonV2Size, BadgeVariant, CheckboxState, DropdownMenuItem } from "./RamusPrimitives";
import { UserChip, PrincipalCell, Chip, Toolbar, ToolbarGroup, ToolbarSeparator, Alert, InputOTP, MultiSelect, Calendar, DateTimeEditor, Table, TableHeader, TableBody, TableFooter, TableRow, TableHead, TableCell, TableCaption, DataGridLite, EmptyState, Breadcrumbs, ResizablePanels, MessageCard, FileCard, SearchCommand, COMPOSER_FORMATS, ComposerToolbar, SettingsRow } from "./RamusPatterns";
import type { GridColumn, ComposerFormat } from "./RamusPatterns";
import { StructuredCard, OptionRow, OptionGroup, Hint, CardFooter, ActionRow, ContextMenu, ActionSheet, IconColorPicker, SymbolPicker, AlertDialog, StatusDialog, Toast, Toaster, FileDropzone, Disclosure } from "./RamusAdvanced";
import type { ActionItem, IconChoice, IconColorValue, SymbolChoice, StatusDraft, ToastItem } from "./RamusAdvanced";
import "./ramus.css";
import "./ramus-primitives.css";
import "./ramus-patterns.css";
import "./ramus-advanced.css";
import "./catalog.css";

const SAMPLE_DATE = "2026-11-09";
const samplePortrait = "data:image/svg+xml," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="120" height="120" viewBox="0 0 120 120"><rect width="120" height="120" fill="#dedbd1"/><circle cx="60" cy="46" r="22" fill="#989183"/><path d="M18 120c0-33 18-50 42-50s42 17 42 50" fill="#777969"/><path d="M38 44c-4-29 49-33 47 4-12-3-24-10-31-19-3 9-8 13-16 15" fill="#514e46"/></svg>');
const types = [
  { value: "doc", label: "Doc", description: "문서와 아이디어" },
  { value: "table", label: "Table", description: "구조화된 데이터" },
  { value: "board", label: "Board", description: "작업과 진행 상태" },
  { value: "archived", label: "Archived", disabled: true },
];
const commands = [
  { id: "create", label: "Create document", description: "새 샘플 문서 만들기", keywords: ["문서", "생성"], shortcut: "N" },
  { id: "table", label: "Open table", description: "프로젝트 테이블 보기", keywords: ["표", "데이터"], shortcut: "G T" },
  { id: "settings", label: "Workspace settings", description: "로컬 설정 미리보기", keywords: ["설정"], shortcut: "G S" },
  { id: "disabled", label: "Unavailable action", disabled: true },
];
const user = { name: "Sample Editor", imageUrl: samplePortrait, presence: "online" as const, subtitle: "Design workspace" };
function Glyph({ name = "plus" }: { name?: "plus" | "search" | "arrow" | "grid" | "check" | "file" | "sun" | "moon" }) {
  const paths = { plus: "M12 5v14M5 12h14", search: "m20 20-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0", arrow: "M5 12h14m-6-6 6 6-6 6", grid: "M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z", check: "m5 12 4 4L19 6", file: "M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6", sun: "M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0", moon: "M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11" };
  return <svg aria-hidden="true" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"><path d={paths[name]} /></svg>;
}
function Note({ children }: { children: React.ReactNode }) { return <p className="hc-note">{children}</p>; }
function Readout({ children }: { children: React.ReactNode }) { return <div className="hc-readout" role="status"><span className="hc-live-dot" />{children}</div>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <div className="hc-field"><span className="hc-small-label">{label}</span>{children}</div>; }
function Block({ title, children }: { title: string; children: React.ReactNode }) { return <div className="hc-demo-block"><h4>{title}</h4>{children}</div>; }

function HeroPreview() {
  const [value, setValue] = React.useState(["doc", "table"]);
  const [date, setDate] = React.useState(SAMPLE_DATE);
  return <div className="hc-hero-preview">
    <div className="hc-preview-main"><div className="hc-preview-top"><span className="hc-eyebrow">WORKSPACE / LOCAL PREVIEW</span><Badge variant="outline">v2</Badge></div>
      <div className="hc-profile-line"><Avatar name="Sample Editor" src={samplePortrait} size="xl" showPresence online /><div><strong>작은 디테일, 하나의 언어.</strong><span>Sample workspace · Design collection</span></div></div>
      <Separator /><div className="hc-preview-picker"><MultiSelect options={types} value={value} onValueChange={setValue} label="Type" placeholder="유형 검색 또는 추가" /></div>
      <div className="hc-preview-bottom"><span>선택한 유형 {value.length}개</span><ButtonV2 size="sm" onClick={() => setValue(["doc", "table"])}>샘플 초기화 <Glyph name="arrow" /></ButtonV2></div>
    </div>
    <div className="hc-preview-calendar"><span className="hc-eyebrow">PLAN YOUR NEXT STEP</span><Calendar value={date} onValueChange={setDate} locale="en-US" /><span className="hc-calendar-caption">Selected · {date}</span></div>
  </div>;
}
function ButtonsDemo() {
  const [last, setLast] = React.useState("버튼을 눌러 상태를 확인하세요.");
  const variants: ButtonV2Variant[] = ["default", "destructive", "outline", "secondary", "ghost", "link", "text"];
  const sizes: ButtonV2Size[] = ["xs", "sm", "default", "lg", "icon-sm", "icon", "icon-lg"];
  return <><Block title="7 variants"><div className="hc-button-matrix">{variants.map(v => <div className="hc-variant-cell" key={v}><ButtonV2 variant={v} onClick={() => setLast(`${v} 선택됨`)}>{v === "destructive" ? "Delete item" : "Create item"}</ButtonV2><code>{v}</code></div>)}</div></Block>
    <Block title="7 sizes"><div className="hc-size-line">{sizes.map(s => <div className="hc-variant-cell" key={s}><ButtonV2 size={s} variant="outline" aria-label={`${s} 샘플 버튼`} onClick={() => setLast(`${s} 크기 선택됨`)}>{s.startsWith("icon") ? <Glyph /> : "Button"}</ButtonV2><code>{s}</code></div>)}</div></Block>
    <div className="hc-inline"><ButtonV2 disabled>Disabled</ButtonV2><ButtonV2 variant="outline" disabled>Disabled outline</ButtonV2><ButtonV2 onClick={() => setLast("로컬 저장 완료")}><Glyph name="check" /> Save locally</ButtonV2></div><Readout>{last}</Readout><Note>공개 모듈에 정의된 크기는 7개입니다. 가상의 추가 크기는 만들지 않았습니다.</Note></>;
}
function InputsDemo() {
  const id = React.useId(); const [text, setText] = React.useState("Product design"); const [notes, setNotes] = React.useState("아이디어를 짧게 기록하고, 팀과 함께 다듬어 보세요.");
  return <><div className="hc-split"><div className="hc-field"><LabelV2 htmlFor={id}>Workspace name</LabelV2><InputV2 id={id} value={text} onChange={e => setText(e.target.value)} placeholder="Enter a name" /><Note>기본 높이와 부드러운 필드 곡률</Note></div><div className="hc-field"><LabelV2 htmlFor={`${id}-invalid`}>Validation state</LabelV2><InputV2 id={`${id}-invalid`} aria-invalid="true" aria-describedby={`${id}-error`} defaultValue="" placeholder="Required value" /><p id={`${id}-error`} className="hc-error">샘플 오류 상태입니다.</p></div></div><InputV2 aria-label="비활성 입력" placeholder="Disabled input" disabled /><div className="hc-field"><LabelV2 htmlFor={`${id}-note`}>Description</LabelV2><TextareaV2 id={`${id}-note`} value={notes} onChange={e => setNotes(e.target.value)} rows={3} /></div><Readout>{text.length} characters · textarea {notes.length} characters</Readout></>;
}
function ChecksDemo() {
  const [state, setState] = React.useState<CheckboxState>("indeterminate");
  return <><div className="hc-stack"><label className="hc-control-label"><Checkbox checked={state} onCheckedChange={setState} />부분 선택된 컬렉션</label><label className="hc-control-label"><Checkbox defaultChecked />이미 선택된 항목</label><label className="hc-control-label"><Checkbox />선택하지 않은 항목</label><label className="hc-control-label"><Checkbox checked disabled />수정할 수 없는 항목</label></div><div className="hc-inline"><ButtonV2 size="sm" variant="outline" onClick={() => setState("indeterminate")}>부분 선택으로 복원</ButtonV2><code>{String(state)}</code></div></>;
}
function SwitchesDemo() {
  const [md, setMd] = React.useState(true), [sm, setSm] = React.useState(false), [xs, setXs] = React.useState(true);
  return <><div className="hc-switch-row"><code>md</code><span>Workspace notifications</span><Switch size="md" aria-label="Workspace notifications" checked={md} onCheckedChange={setMd} /></div><div className="hc-switch-row"><code>sm</code><span>Show previews</span><Switch size="sm" aria-label="Show previews" checked={sm} onCheckedChange={setSm} /></div><div className="hc-switch-row"><code>xs</code><span>Compact indicator</span><Switch size="xs" aria-label="Compact indicator" checked={xs} onCheckedChange={setXs} /></div><div className="hc-switch-row"><code>disabled</code><span>Managed setting</span><Switch disabled checked aria-label="Managed setting" /></div><Readout>md {md ? "on" : "off"} · sm {sm ? "on" : "off"} · xs {xs ? "on" : "off"}</Readout></>;
}
function RadiosDemo() {
  const [access, setAccess] = React.useState("private"); const id = React.useId();
  return <fieldset className="hc-fieldset"><legend>Create a space · Visibility</legend>{[{ value: "private", title: "Private space", text: "초대한 샘플 멤버만 접근" }, { value: "workspace", title: "Workspace space", text: "워크스페이스 구성원에게 공개" }, { value: "public", title: "Public space", text: "비활성 상태 예시" }].map(o => <label className="hc-radio-card" key={o.value} data-selected={access === o.value}><RadioControl name={id} value={o.value} checked={access === o.value} onChange={() => setAccess(o.value)} disabled={o.value === "public"} /><span><strong>{o.title}</strong><small>{o.text}</small></span></label>)}<Readout>선택한 범위: {access}</Readout><Note>CreateSpaceRadio 화면 패턴을 RadioControl로 구성한 로컬 샘플입니다.</Note></fieldset>;
}
function AvatarsDemo() {
  return <><Block title="5 sizes · initials"><div className="hc-size-line">{(["xs", "sm", "md", "lg", "xl"] as const).map(size => <div className="hc-variant-cell" key={size}><Avatar name="Sample Designer" size={size} /><code>{size}</code></div>)}</div></Block><Block title="Image / explicit initials / presence"><div className="hc-size-line"><div className="hc-variant-cell"><Avatar name="Sample portrait" src={samplePortrait} size="xl" /><code>data SVG</code></div><div className="hc-variant-cell"><Avatar name="Studio Sample" initials="SS" size="xl" /><code>initials</code></div><div className="hc-variant-cell"><Avatar name="Online sample" src={samplePortrait} size="xl" showPresence online presenceLabel="온라인" /><code>online</code></div><div className="hc-variant-cell"><Avatar name="Quiet sample" size="xl" showPresence online={false} /><code>no presence</code></div></div></Block><Note>이미지는 이 파일에 내장한 일반 인물 실루엣 SVG입니다. 외부 이미지와 실제 프로필은 사용하지 않습니다. 온라인 presence만 관측 근거가 있습니다.</Note></>;
}
function PrincipalsDemo() {
  return <><div className="hc-principal-feature"><UserChip user={user} size="profile" showPresence /><div><strong>Sample Editor</strong><p>Profile · local sample</p></div></div><Separator /><Block title="UserChip"><div className="hc-stack"><UserChip user={user} showPresence /><UserChip user={{ name: "Sample Reviewer" }} size="sm" /><UserChip user={{ name: "Inactive Sample", deactivated: true }} /></div></Block><Block title="PrincipalCell"><div className="hc-stack"><PrincipalCell principal={user}><Badge variant="muted">Editor</Badge></PrincipalCell><PrincipalCell principal={null} settled /><PrincipalCell settled /></div></Block></>;
}
function BadgesDemo() { const variants: BadgeVariant[] = ["default", "secondary", "destructive", "outline", "muted", "success", "warning", "private"]; return <><div className="hc-badge-grid">{variants.map(v => <div key={v} className="hc-badge-item"><Badge variant={v}>{v}</Badge><code>{v}</code></div>)}</div><Note>8개 variant는 공개 모듈 정의에서 확인했습니다. 모든 variant의 실제 화면 노출을 관측한 것은 아닙니다.</Note></>; }
function ChipsDemo() {
  const [labels, setLabels] = React.useState(["Design", "Research", "Product"]); const [active, setActive] = React.useState(false);
  return <><div className="hc-inline">{labels.map(l => <Chip key={l} onRemove={() => setLabels(v => v.filter(x => x !== l))}>{l}</Chip>)}<Chip selected={active} onClick={() => setActive(v => !v)}>Interactive</Chip><Chip disabled onRemove={() => undefined}>Disabled</Chip></div><ButtonV2 size="sm" variant="ghost" onClick={() => setLabels(["Design", "Research", "Product"])}>칩 복원</ButtonV2><Readout>{labels.length} removable chips · interactive {active ? "selected" : "unselected"}</Readout></>;
}
function SelectsDemo() {
  const [tz, setTz] = React.useState<string | null>("seoul"); const [role, setRole] = React.useState<string | null>("editor");
  return <><Field label="Searchable single select"><Select label="Timezone" options={[{ value: "seoul", label: "Asia/Seoul · GMT+09:00" }, { value: "london", label: "Europe/London · GMT+00:00" }, { value: "new-york", label: "America/New_York · GMT-05:00" }, { value: "disabled", label: "Unavailable timezone", disabled: true }]} value={tz} onValueChange={setTz} searchable searchPlaceholder="Search timezones" /></Field><div className="hc-split"><Field label="Single choice"><Select label="Sample role" value={role} onValueChange={setRole} options={[{ value: "editor", label: "Editor" }, { value: "viewer", label: "Viewer" }, { value: "owner", label: "Owner", disabled: true }]} /></Field><Field label="Disabled"><Select label="Disabled select" options={[]} disabled placeholder="Unavailable" /></Field></div><Readout>{tz} · {role}</Readout></>;
}
function MultiSelectDemo() {
  const [selected, setSelected] = React.useState(["doc", "table"]); const [empty, setEmpty] = React.useState<string[]>([]); const [disabled, setDisabled] = React.useState(false);
  return <><MultiSelect options={types} value={selected} onValueChange={setSelected} label="Type · multiple selection" placeholder="Search types" emptyLabel="일치하는 유형이 없습니다." disabled={disabled} /><div className="hc-inline"><ButtonV2 variant="outline" size="sm" onClick={() => setSelected(["doc", "table"])}>Doc + Table 복원</ButtonV2><ButtonV2 variant="ghost" size="sm" disabled={disabled || selected.length === 0} onClick={() => setSelected([])}>Clear all</ButtonV2><label className="hc-control-label"><Switch size="xs" checked={disabled} onCheckedChange={setDisabled} aria-label="Disable multi select" />Disabled</label></div><Readout>선택 배열: [{selected.join(", ")}]</Readout><Separator /><MultiSelect options={[]} value={empty} onValueChange={setEmpty} label="Empty options" placeholder="빈 목록 열기" emptyLabel="선택할 항목이 없습니다." /><Note>검색, 복수 선택, 선택 칩 제거, 전체 해제, 키보드 탐색을 시험할 수 있습니다. Type의 Doc + Table 동시 선택이 원본에서 관측되었습니다.</Note></>;
}
function MenuDemo() {
  const [checked, setChecked] = React.useState(true); const [sort, setSort] = React.useState("recent"); const [action, setAction] = React.useState("메뉴의 액션은 로컬 상태만 변경합니다.");
  const items: DropdownMenuItem[] = [{ id: "label", type: "label", label: "Collection actions" }, { id: "new", label: "New document", icon: <Glyph name="file" />, shortcut: "N", onSelect: () => setAction("New document 실행됨") }, { id: "sep1", type: "separator" }, { id: "preview", type: "checkbox", label: "Show preview", checked, onCheckedChange: setChecked }, { id: "recent", type: "radio", label: "Recently edited", checked: sort === "recent", onSelect: () => setSort("recent") }, { id: "name", type: "radio", label: "Name A to Z", checked: sort === "name", onSelect: () => setSort("name") }, { id: "move", type: "submenu", label: "Move to", items: [{ id: "design", label: "Design space", onSelect: () => setAction("Design space로 이동한 샘플") }, { id: "archive", label: "Archive", onSelect: () => setAction("Archive로 이동한 샘플") }] }, { id: "sep2", type: "separator" }, { id: "unavailable", label: "Unavailable action", disabled: true }, { id: "delete", label: "Delete sample", destructive: true, onSelect: () => setAction("삭제 요청 샘플, 실제 데이터 변경 없음") }];
  return <><div className="hc-popup-stage"><DropdownMenu trigger={<><Glyph name="grid" /> Collection menu</>} label="Collection menu" items={items} /><span className="hc-muted">Action · checkbox · radio · submenu</span></div><Readout>{action}</Readout><div className="hc-kv"><span>Show preview</span><code>{String(checked)}</code><span>Sort order</span><code>{sort}</code></div><Note>서브메뉴는 Move to에서 열립니다. 방향키, Enter, Escape를 지원하는 독립 구현입니다. 앱 단축키 실행은 포함하지 않습니다.</Note></>;
}
function TooltipDemo() { return <><div className="hc-popup-stage"><Tooltip content="새 샘플 문서를 만듭니다" side="top"><ButtonV2 variant="outline"><Glyph /> Hover or focus</ButtonV2></Tooltip></div><Note>포인터를 올리거나 키보드로 초점을 이동하세요. 원본 data-slot=tooltip-content와 내비게이션 tooltip이 확인되었습니다.</Note></>; }
function PopoverDemo() {
  const [name, setName] = React.useState("Untitled collection"); const id = React.useId();
  return <><div className="hc-popup-stage"><Popover label="Collection properties" trigger="Edit properties" align="start"><div className="hc-stack"><strong>Collection properties</strong><LabelV2 htmlFor={id}>Name</LabelV2><InputV2 id={id} value={name} onChange={e => setName(e.target.value)} /><Note>비모달 popover · 메모리 안에서만 편집</Note></div></Popover></div><Readout>{name}</Readout><Note>원본의 링크 popover와 profile 모듈의 정적 정의를 참고했습니다. 바깥 클릭 또는 Escape로 닫습니다.</Note></>;
}
function HoverCardDemo() { return <><div className="hc-popup-stage"><HoverCard label="Sample profile" trigger={<UserChip user={{ name: "Sample Designer" }} />} align="start"><div className="hc-stack"><Avatar name="Sample Designer" src={samplePortrait} size="xl" /><strong>Sample Designer</strong><p className="hc-muted">Design systems · Local example</p><Badge variant="outline">Profile preview</Badge></div></HoverCard></div><Note>HoverCard는 모듈 정의만 확인했습니다. hover 지연과 포커스 동작은 독립 구현의 기본값입니다.</Note></>; }
function TabsDemo() { const items = [{ value: "overview", label: "Overview", content: <div className="hc-tab-example"><strong>한눈에 보는 프로젝트</strong><p>최근 변경 사항과 주요 문서를 정리합니다.</p></div> }, { value: "activity", label: "Activity", content: <div className="hc-tab-example"><strong>최근 활동</strong><p>2026-11-09 · 샘플 컬렉션 업데이트</p></div> }, { value: "disabled", label: "Disabled", disabled: true, content: null }]; return <><Block title="Segmented"><Tabs label="Segmented example" items={items} variant="segmented" /></Block><Block title="Underline"><Tabs label="Underline example" items={items} variant="underline" /></Block><Note>각 Tabs는 독립된 선택 상태를 가집니다. 방향키로 탭 사이를 이동할 수 있습니다.</Note></>; }
function CalendarDemo() { const [date, setDate] = React.useState(SAMPLE_DATE); return <><div className="hc-calendar-demo"><Calendar value={date} onValueChange={setDate} locale="en-US" /></div><Readout>Selected date · {date}</Readout><Note>월 이동, Today, 날짜 선택과 키보드 이동을 제공합니다. 원본의 전체 이벤트 달력이나 예약 기능 복제가 아닙니다. Today는 실행하는 날을 가리킵니다.</Note></>; }
function DateDemo() { const [date, setDate] = React.useState("2026-11-09T09:30"); const [only, setOnly] = React.useState(SAMPLE_DATE); return <><Field label="Date + time"><DateTimeEditor value={date} onValueChange={setDate} label="Schedule date" /></Field><Field label="Date only"><DateTimeEditor value={only} onValueChange={setOnly} label="Due date" includeTime={false} /></Field><DateTimeEditor value="2026-11-09T09:30" onValueChange={() => undefined} disabled label="Disabled date" /><Readout>{date || "No date selected"}</Readout><Note>날짜는 달력 popup, 시간은 네이티브 로컬 time input을 사용합니다. 관측된 TimeEditor listbox 전체를 복제한 것은 아니며 timezone 변환도 하지 않습니다.</Note></>; }
function OTPDemo() { const [value, setValue] = React.useState("123"); return <><Field label="6-digit sample"><InputOTP value={value} onValueChange={setValue} label="샘플 숫자 입력" /></Field><Field label="Disabled"><InputOTP value="123456" onValueChange={() => undefined} disabled label="비활성 샘플 숫자" /></Field><Readout>{value.length} / 6 digits</Readout><Note>숫자 입력과 붙여넣기만 가능한 UI 슬롯 데모입니다. 인증 코드 발급, 검증, SMS, 계정 연결은 없습니다. 실제 코드는 입력하지 마세요.</Note></>; }
