function ComposerDemo() { const [formats, setFormats] = React.useState<ComposerFormat[]>(["Bold"]); const [inserted, setInserted] = React.useState("삽입한 항목 없음"); return <><div className="hc-composer-surface"><TextareaV2 aria-label="로컬 메시지" defaultValue="이 공간에서 다음 프로젝트를 함께 정리해 보세요." rows={3} /><ComposerToolbar value={formats} onValueChange={setFormats} mentions={[{ id: "sample", label: "Sample Editor" }, { id: "review", label: "Sample Reviewer" }]} symbolItems={[{ id: "check", label: "Check mark" }, { id: "star", label: "Star" }]} onInsert={(kind, item) => setInserted(`${kind}: ${item.label}`)} /></div><Readout>{formats.length ? formats.join(", ") : "선택한 서식 없음"} · {inserted}</Readout><details className="hc-details"><summary>지원하는 서식 {COMPOSER_FORMATS.length}개</summary><p>{COMPOSER_FORMATS.join(" · ")}</p></details><Note>서식 버튼의 선택 상태와 검색 picker만 시연합니다. 실제 rich-text editor 변환이나 링크 접근은 하지 않습니다. Symbol picker에는 이미지나 이모지를 넣지 않았습니다.</Note></>; }
