function GridDemo() { const [mode, setMode] = React.useState("data"); const [selected, setSelected] = React.useState<string[]>(["S02"]); const columns: GridColumn<SampleRow>[] = [{ key: "name", header: "Name", render: r => <span className="hc-grid-name"><Glyph name="file" />{r.name}</span> }, { key: "type", header: "Type", render: r => <Badge variant="outline">{r.type}</Badge> }, { key: "updated", header: "Updated" }, { key: "size", header: "Items" }]; return <><div className="hc-inline">{["data", "loading", "empty"].map(m => <ButtonV2 key={m} variant={mode === m ? "secondary" : "ghost"} size="sm" aria-pressed={mode === m} onClick={() => setMode(m)}>{m}</ButtonV2>)}</div><DataGridLite rows={mode === "empty" ? [] : rows} columns={columns} getRowId={r => r.id} label="Sample documents" selectable selectedIds={selected} onSelectionChange={setSelected} loading={mode === "loading"} emptyLabel="No documents in this view" maxHeight={320} /><Readout>Selected rows · {selected.length ? selected.join(", ") : "none"}</Readout><Note>AG Grid 목록 관측을 참고한 DataGridLite 권장조합입니다. 기본 정렬, 문자열 필터, 행 선택, loading/empty만 구현합니다. AG Grid 전체 구현, 셀 편집, 컬럼 리사이즈, 가상화가 아닙니다.</Note></>; }
