function AlertsDemo() { const [show, setShow] = React.useState(true); return <><Alert title="모든 변경은 로컬에서만 유지됩니다" icon={<Glyph name="check" />}>검색, 선택, 정렬과 편집은 현재 열린 데모의 메모리 상태만 변경합니다.</Alert>{show && <Alert variant="destructive" title="샘플 오류 상태"><div className="hc-inline"><span>작업을 완료하지 못했습니다. 실제 요청은 발생하지 않았습니다.</span><ButtonV2 variant="outline" size="xs" onClick={() => setShow(false)}>Dismiss</ButtonV2></div></Alert>}{!show && <ButtonV2 size="sm" variant="ghost" onClick={() => setShow(true)}>오류 알림 복원</ButtonV2>}<Note>Alert의 정적 스타일과 AlertDialog 화면 관측은 별개입니다. 확인 대화상자는 아래 CatalogDialog 샘플에서 다룹니다.</Note></>; }
