function ToastDemo() {
  const [inline, setInline] = React.useState(true); const [items, setItems] = React.useState<ToastItem[]>([]); const [action, setAction] = React.useState("알림 동작을 시험하세요."); const serial = React.useRef(0);
  const dismiss = (id: string) => setItems(v => v.filter(item => item.id !== id));
  function addToast(persistent = false) { serial.current += 1; const id = "catalog-toast-" + serial.current; const item: ToastItem = { id, announcement: "로컬 샘플 저장 알림", title: "Sample saved locally", description: persistent ? "닫기 전까지 유지되는 샘플입니다." : "6초 후 닫히는 로컬 알림입니다. hover 또는 focus 중에는 일시 정지합니다.", duration: persistent ? null : 6000, action: { label: "Undo", onClick: () => setAction("Undo 선택됨, 실제 저장이나 복구 작업 없음") } }; setItems(v => [...v.slice(-2), item]); setAction(persistent ? "유지형 알림 추가됨" : "6초 알림 추가됨"); }
  return <><div className="hc-toast-inline">{inline ? <Toast item={{ id: "inline-specimen", announcement: "정적 위치 토스트 미리보기", title: "Your sample is ready", description: "실측된 커스텀 토스트 카드의 시각 구조입니다.", duration: null, action: { label: "Review", onClick: () => setAction("Review 선택됨, 외부 이동 없음"), dismissOnAction: false } }} onDismiss={() => setInline(false)} dismissLabel="Dismiss" /> : <ButtonV2 size="sm" variant="outline" onClick={() => setInline(true)}>미리보기 복원</ButtonV2>}</div><div className="hc-measure-strip"><span><b>356</b>width</span><span><b>16</b>radius</span><span><b>16</b>padding</span><span><b>12</b>gap</span></div><div className="hc-inline"><ButtonV2 size="sm" variant="outline" onClick={() => addToast()}>Show timed toast</ButtonV2><ButtonV2 size="sm" variant="ghost" onClick={() => addToast(true)}>Persistent toast</ButtonV2><ButtonV2 size="sm" variant="ghost" disabled={!items.length} onClick={() => setItems([])}>Dismiss all</ButtonV2></div><Toaster items={items} onDismiss={dismiss} label="카탈로그 로컬 알림" dismissLabel="Dismiss" /><Readout>{action} · viewport 알림 {items.length}개</Readout><Note>references/evidence/toast-computed.json의 실제 Ramus 커스텀 group 실측: width 356px, radius 16px, padding 16px, gap 12px, 제목·설명 14px/20px, CTA 높이 24px/radius 8px. 높이는 내용에 따라 달라집니다. 일반 Sonner 기본 recipe와 구분하며 viewport 배치·타이머·스택은 독립 구현입니다.</Note></>;
}
