const statuses: Record<SourceStatus, string> = { observed: "UI+정적정의", static: "정적정의만", composed: "권장조합" };
function Status({ value }: { value: SourceStatus }) { return <span className={`hc-source-status hc-source-${value}`}><i />{statuses[value]}</span>; }
function StoryCard({ story, theme }: { story: Story; theme: RamusTheme }) { return <article className={`hc-card${story.wide ? " hc-card-wide" : ""}`} id={`hc-${story.id}`}><header className="hc-card-head"><div><h3>{story.title}</h3><p>{story.subtitle}</p></div><Status value={story.status} /></header><div className="hc-specimen">{story.render(theme)}</div><footer className="hc-card-footer"><span>{story.source}</span><details className="hc-code"><summary>React API</summary><pre><code>{story.api}</code></pre></details></footer></article>; }

export default function RamusCatalog() {
  const [theme, setTheme] = React.useState<RamusTheme>("light");
  const [query, setQuery] = React.useState("");
  const [compact, setCompact] = React.useState(false);
  const [sourceFilter, setSourceFilter] = React.useState("all");
  const [active, setActive] = React.useState("overview");
  const searchId = React.useId();
  const normalized = query.toLocaleLowerCase().trim();
  const visible = stories.filter(s => (sourceFilter === "all" || s.status === sourceFilter) && `${s.title} ${s.subtitle} ${s.keywords || ""} ${s.source} ${groups.find(g => g.id === s.group)?.name || ""}`.toLocaleLowerCase().includes(normalized));
  function go(id: string) { setActive(id); document.getElementById(`hc-${id}`)?.scrollIntoView({ behavior: "smooth", block: "start" }); }
  return <RamusProvider theme={theme} className={`hc-shell${compact ? " hc-compact" : ""}`}>
    <a href="#hc-main" className="hc-skip">컴포넌트 카탈로그로 건너뛰기</a>
    <aside className="hc-sidebar"><a className="hc-brand" href="#hc-overview" onClick={() => setActive("overview")}><span className="hc-brand-mark"><Glyph name="grid" /></span><span>Ramus <small>DESIGN EXPLORER</small></span><b>v2</b></a><div className="hc-sidebar-caption">로컬 컴포넌트 카탈로그</div><nav className="hc-nav" aria-label="카탈로그 섹션"><button type="button" className="hc-nav-overview" data-active={active === "overview"} onClick={() => go("overview")}><Glyph name="grid" /><span>Overview</span></button>{groups.map(g => <button type="button" key={g.id} data-active={active === g.id} onClick={() => go(g.id)}><span className="hc-nav-number">{g.number}</span><span>{g.name}</span><small>{stories.filter(s => s.group === g.id).length}</small></button>)}</nav><div className="hc-sidebar-bottom"><span className="hc-eyebrow">REFERENCE LIBRARY</span><a href="./references/index.html">원본 캡처 64개 <Glyph name="arrow" /></a><a href="./Onboarding-Reference.html">v1 온보딩 참조 <Glyph name="arrow" /></a><div className="hc-local-badge"><span className="hc-live-dot" /> Local only · React</div><p>독립 재구성 UI입니다.<br />원본 제품의 전체 기능 복제가 아닙니다.</p></div></aside>
    <div className="hc-content"><header className="hc-topbar"><div className="hc-topbar-title"><span>Design system</span><span className="hc-muted">/</span><strong>Component catalog</strong></div><div className="hc-topbar-controls"><div className="hc-theme-control" aria-label="카탈로그 테마">{(["light", "dark", "onboarding"] as const).map(t => <button key={t} type="button" aria-pressed={theme === t} onClick={() => setTheme(t)}>{t === "light" ? <Glyph name="sun" /> : t === "dark" ? <Glyph name="moon" /> : null}<span>{t === "onboarding" ? "Onboarding" : t === "light" ? "Light" : "Dark"}</span></button>)}</div><label className="hc-density"><Switch size="xs" checked={compact} onCheckedChange={setCompact} aria-label="Compact catalog spacing" /><span>Compact</span></label></div></header>
    <main id="hc-main"><section id="hc-overview" className="hc-hero"><div className="hc-hero-heading"><div><span className="hc-eyebrow"><span className="hc-live-dot" /> RECONSTRUCTED FROM REAL UI</span><h1>확인한 UI의 다양한 표정을,<br /><span>한곳에서 살펴보세요.</span></h1><p className="hc-hero-description">실제로 작동하는 React 컴포넌트와 확인된 디자인 근거.<br />선택하고, 열어 보고, 테마를 바꾸며 디테일을 탐색하세요.</p></div><div className="hc-edition"><span>RAMUS</span><strong>02</strong><small>VISUAL CATALOG<br />2026.11.09</small></div></div>
      <div className="hc-stats"><div><strong>30<small> +2</small></strong><span>공유 정의 그룹 · 초기 30 + 추가 2</span></div><div><strong>293</strong><span>고유 토큰</span></div><div><strong>64<small> 16+48</small></strong><span>원본 캡처 · 추가 48개 포함</span></div><div><strong>{stories.length}</strong><span>작동하는 카탈로그 카드</span></div></div>
      <HeroPreview />
      <div className="hc-legend"><strong>근거의 수준을 구분합니다.</strong><span><Status value="observed" /> 화면과 정의를 함께 확인</span><span><Status value="static" /> 코드 정의만 확인</span><span><Status value="composed" /> 원본 패턴을 재구성</span></div>
      <p className="hc-evidence-note">미리보기는 RamusComponents.tsx, RamusPrimitives.tsx, RamusPatterns.tsx, RamusAdvanced.tsx의 실제 export를 import해 렌더링합니다. 총 73개 값 export(9 + 19 + 29 + 16)에는 상수 COMPOSER_FORMATS 1개가 포함되며 컴포넌트 73개를 뜻하지 않습니다. 원 서비스 소스나 공식 패키지가 아닌 독립 구현입니다. 조사 범위는 초기 공유 정의 30그룹과 추가 EntityMenu / StructuredCard 2그룹이며, 권장조합은 별도 분류합니다. 제품 전체 기능이나 모든 컴포넌트를 전수 복제한 것은 아닙니다.</p>
    </section>
    <div className="hc-browser-bar"><div className="hc-search"><Glyph name="search" /><label className="hc-sr-only" htmlFor={searchId}>컴포넌트 검색</label><input id={searchId} value={query} onChange={e => setQuery(e.target.value)} placeholder="컴포넌트 검색... Avatar, MultiSelect, Calendar" />{query && <button type="button" aria-label="검색어 지우기" onClick={() => setQuery("")}>Clear</button>}</div><label className="hc-filter"><span className="hc-sr-only">근거 수준 필터</span><select value={sourceFilter} onChange={e => setSourceFilter(e.target.value)}><option value="all">전체 근거 수준</option><option value="observed">UI+정적정의</option><option value="static">정적정의만</option><option value="composed">권장조합</option></select></label><span className="hc-result-count" role="status">{visible.length} / {stories.length} cards</span></div>
    <div className="hc-story-sections">{visible.length === 0 && <div className="hc-no-results"><Glyph name="search" /><h2>일치하는 컴포넌트가 없습니다.</h2><p>영문 API 이름이나 한글 분류로 다시 검색하세요.</p><ButtonV2 variant="outline" onClick={() => { setQuery(""); setSourceFilter("all"); }}>전체 보기</ButtonV2></div>}{groups.map(g => { const list = visible.filter(s => s.group === g.id); if (!list.length) return null; return <section key={g.id} id={`hc-${g.id}`} className="hc-section"><header className="hc-section-heading"><span className="hc-section-number">{g.number}</span><div><h2>{g.name}</h2><p>{g.description}</p></div><span className="hc-section-count">{list.length} specimens</span></header><div className="hc-card-grid">{list.map(s => <StoryCard key={s.id} story={s} theme={theme} />)}</div></section>; })}</div>
    <footer className="hc-page-footer"><div><span className="hc-eyebrow">BUILT FOR EXPLORATION</span><h2>화면 너머의 근거까지.</h2><p>정적 정의와 관측 화면을 구분하고, 권장조합은 별도로 표시했습니다.</p></div><div className="hc-footer-links"><a href="./references/index.html">원본 스크린샷 인덱스 <Glyph name="arrow" /></a><a href="./Onboarding-Reference.html">온보딩 참조 페이지 <Glyph name="arrow" /></a><a href="./RAMUS-DESIGN-SYSTEM.md">디자인 시스템 문서 <Glyph name="arrow" /></a></div><div className="hc-footer-notes"><p><strong>근거</strong> module-component-inventory.md · css-component-inventory.md · measure-*.json · references/evidence/toast-computed.json. 공유 정의 초기 30그룹 + 추가 EntityMenu / StructuredCard 2그룹과 별도 권장조합을 구분합니다. 원본 캡처는 64개(기존 16 + 추가 48)입니다. 참조 이미지는 references/index.html의 상대 경로 구조를 유지합니다. 온보딩 참조 링크는 배포 폴더에 해당 HTML이 포함될 때 열립니다.</p><p><strong>제약</strong> overlay는 .ramus 내부에서 렌더링되며 portal / 충돌 회피 엔진이 없습니다. DataGridLite는 기본 동작만 제공합니다. 날짜·시간은 로컬 샘플입니다. 설정과 선택은 새로고침하면 초기화됩니다. Advanced 메뉴와 시트의 원본 UI 노출은 미확인이며, modal / focus / timer 동작은 재구성입니다. 파일 내용 파싱·전송과 실제 상태 만료 예약은 하지 않습니다. 외부 요청·이미지·스토리지·실제 사용자 정보·로고는 사용하지 않습니다.</p><p><strong>Theme scope</strong> Light / Dark는 토큰 scope에 적용합니다. Onboarding은 독립적으로 정규화한 light 기반 테마이며 원본의 모든 온보딩 상태와 일치한다는 의미가 아닙니다. Compact는 카탈로그 여백만 줄이고 원본 컴포넌트 크기는 바꾸지 않습니다.</p></div></footer>
    </main></div>
  </RamusProvider>;
}
